use std::collections::HashMap;

fn make_counter(start: u32, step: u32) -> impl FnMut() -> u32 {
    let mut next = start;
    move || {
        let value = next;
        next += step;
        value
    }
}

fn compose<A, B, C>(f: impl Fn(A) -> B, g: impl Fn(B) -> C) -> impl Fn(A) -> C {
    move |a| g(f(a))
}

fn apply_n(f: impl Fn(i64) -> i64, n: usize, x: i64) -> i64 {
    (0..n).fold(x, |acc, _| f(acc))
}

fn memoize(f: impl Fn(u64) -> u64) -> impl FnMut(u64) -> u64 {
    let mut cache: HashMap<u64, u64> = HashMap::new();
    move |x| *cache.entry(x).or_insert_with(|| f(x))
}

fn retry<T, E>(attempts: usize, mut action: impl FnMut() -> Result<T, E>) -> Result<T, E> {
    let mut result = action();
    for _ in 1..attempts {
        if result.is_ok() {
            break;
        }
        result = action();
    }
    result
}

unitTests:
test("counters keep their own state", || {
    let mut a = make_counter(1, 1);
    let mut b = make_counter(100, 50);
    check_eq((a(), a(), a()), (1, 2, 3));
    check_eq((b(), b()), (100, 150));
    check_eq(a(), 4);
});

test("composing", || {
    let parse_then_double = compose(|s: &str| s.trim().parse::<i32>().unwrap_or(0), |n| n * 2);
    check_eq(parse_then_double(" 21 "), 42);
    let shout = compose(|s: String| s.to_uppercase(), |s| s + "!");
    check_eq(shout("hi".to_string()), "HI!");
});

test("applying n times", || {
    check_eq(apply_n(|x| x * 2, 10, 1), 1024);
    check_eq(apply_n(|x| x + 3, 0, 7), 7);
});

test("memoizing", || {
    use std::cell::Cell;
    let calls = Cell::new(0);
    let mut fast = memoize(|n| { calls.set(calls.get() + 1); n * n });
    check_eq((fast(4), fast(4), fast(5), fast(4)), (16, 16, 25, 16));
    check_eq(calls.get(), 2);
});

test("retrying", || {
    let mut tries = 0;
    let r: Result<&str, String> = retry(5, || { tries += 1; if tries < 3 { Err(format!("fail {tries}")) } else { Ok("done") } });
    check_eq(r, Ok("done"));
    check_eq(tries, 3);
    let mut count = 0;
    let r: Result<(), String> = retry(2, || { count += 1; Err(format!("fail {count}")) });
    check_eq(r, Err("fail 2".to_string()));
    let mut once = 0;
    let _ = retry::<(), ()>(0, || { once += 1; Err(()) });
    check_eq(once, 1);
});

